-- Fakt kartochkalari orqa tomonining ruscha matni — 75-partiya:
-- Shohrux Mirzo, Shukur Xolmirzayev, So'fi Olloyor.

UPDATE fact_cards SET detail_ru = 'Шахрух Мирза родился 20 августа 1377 года в Самарканде, в семье Амира Темура. Юные годы его прошли в Самарканде, где он получил светское и религиозное образование. Источник: Ziyouz.com — раздел «Правители Узбекистана».' WHERE id = 2314;
UPDATE fact_cards SET detail_ru = 'Шахрух Мирза был сыном Сахибкирана Амира Темура. В 1396 году Амир Темур дал ему в суюргал Хорасанский край, и с того года он управлял этими землями. Источник: Ziyouz.com — раздел «Правители Узбекистана».' WHERE id = 2315;
UPDATE fact_cards SET detail_ru = 'После смерти Амира Темура, в марте 1405 года, Шахрух официально взошёл на хорасанский престол как правитель державы Тимуридов. Он велел читать хутбу от своего имени и чеканить монету. Источник: Ziyouz.com — раздел «Правители Узбекистана».' WHERE id = 2316;
UPDATE fact_cards SET detail_ru = 'Шахрух отдал повеление о восстановлении Герата в 1405 году и Балха в 1407-м; был заново отстроен и город Мерв. В его пору улучшилась оросительная система и были освоены новые земли. Источник: Ziyouz.com — раздел «Правители Узбекистана».' WHERE id = 2317;
UPDATE fact_cards SET detail_ru = 'В пору Шахруха в таких городах, как Герат, Самарканд, Бухара, Мешхед, Шираз, развивались науки, было построено множество медресе, мечетей и ханак. В Герате и Ширазе большое внимание уделялось историописанию. Источник: Ziyouz.com — раздел «Правители Узбекистана».' WHERE id = 2318;
UPDATE fact_cards SET detail_ru = 'Сын Шахруха Мирзы Мирзо Улугбек возвёл в Мавераннахре обсерваторию, и там развивались точные науки. В источнике среди его детей упомянуты также Мирза Байсунгур, Ибрагим Султан и Мухаммад Джуки. Источник: Ziyouz.com — раздел «Правители Узбекистана».' WHERE id = 2319;
UPDATE fact_cards SET detail_ru = 'В международной политике Шахрух считал главными мир между государствами и дружественные отношения; его описывают как правителя справедливого и радеющего о покое подданных. Он посылал послов к правителям Китая, Индии, Египта, Шама, Рума и Дешт-и Кипчака. Источник: Ziyouz.com — раздел «Правители Узбекистана».' WHERE id = 2320;
UPDATE fact_cards SET detail_ru = 'Шахрух Мирза умер 19 марта 1447 года в городе Рей. Он правил державой Тимуридов с 1405 по 1447 год. Источник: Ziyouz.com — раздел «Правители Узбекистана».' WHERE id = 2321;

UPDATE fact_cards SET detail_ru = 'Шукур Холмирзаев родился 24 марта 1940 года в Байсунском районе Сурхандарьинской области. Позже он стал одним из известных представителей узбекской прозы. Источник: Ziyouz.com, раздел «Узбекская проза».' WHERE id = 2322;
UPDATE fact_cards SET detail_ru = 'Первые рассказы и очерки писателя начали печататься с 1958 года. В 1963 году он окончил факультет журналистики Ташкентского университета. Источник: Ziyouz.com.' WHERE id = 2323;
UPDATE fact_cards SET detail_ru = 'Первая повесть писателя «Всадник на белом коне» вышла в 1962 году. После неё были изданы повести «Волны» (1963) и «Кому не исполнилось восемнадцати?» (1965). Источник: Ziyouz.com.' WHERE id = 2324;
UPDATE fact_cards SET detail_ru = 'Шукур Холмирзаев известен прежде всего как мастер рассказа. Изданы его сборники «Под далёкими звёздами» (1971), «Жизнь вечна» (1974), «Если сдвинется тяжёлый камень…» (1980), «Дороги, спутники» (1984), «Миндаль зацвёл зимой» (1986), «На горы выпал снег» (1987). Источник: Ziyouz.com.' WHERE id = 2325;
UPDATE fact_cards SET detail_ru = 'Писатель создал романы «Последняя остановка» (1976), «Мост тоньше волоса» (1984), «Путник» (1987), «Пугало» (1992), а также первую книгу романа «Динозавр» (1996). Он же автор драм «Чёрный пояс» (1987) и «Пиршество» (1990). Источник: Ziyouz.com.' WHERE id = 2326;
UPDATE fact_cards SET detail_ru = 'Писатель родился в Байсунском районе Сурхандарьи. Образы природы отразились и в названиях его сборников: «На горы выпал снег» (1987), «Миндаль зацвёл зимой» (1986), «Под далёкими звёздами» (1971). Источник: Ziyouz.com.' WHERE id = 2327;
UPDATE fact_cards SET detail_ru = 'В 1989 году писатель был удостоен республиканской Государственной премии имени Хамзы. В 1991 году ему было присвоено звание народного писателя Узбекистана, а в 1999-м он был награждён орденом «Мехнат шухрати». Источник: Ziyouz.com.' WHERE id = 2328;
UPDATE fact_cards SET detail_ru = 'Шукур Холмирзаев умер 29 сентября 2005 года в Ташкенте. После него осталось богатое литературное наследие: рассказы, повести, романы, такие как «Динозавр», и драмы. Источник: Ziyouz.com.' WHERE id = 2329;

UPDATE fact_cards SET detail_ru = 'Суфи Аллаяр родился в 1644 году в селении Минглар Каттакурганского бекства. Первое образование он получил в школе шейхов. Источник: Ziyouz.com — раздел «Узбекская классическая словесность».' WHERE id = 1975;
UPDATE fact_cards SET detail_ru = 'Он учился в школе шейхов и в обители джуйбарских шейхов в Бухаре. В эту же пору он изучил арабский и персидский языки. Источник: Ziyouz.com — раздел «Узбекская классическая словесность».' WHERE id = 1976;
UPDATE fact_cards SET detail_ru = 'Бухарский хан Абдулазиз-хан назначил его начальником в таможенную управу. Однако он вскоре отказался от этой официальной должности и избрал путь суфизма. Источник: Ziyouz.com — раздел «Узбекская классическая словесность».' WHERE id = 1977;
UPDATE fact_cards SET detail_ru = 'Отказавшись от должности в таможенной управе, он стал учеником известного шейха своего времени Навруза. Исполнив требования пути, он поднялся до звания шейха и вырос в святого мужа. Источник: Ziyouz.com — раздел «Узбекская классическая словесность».' WHERE id = 1978;
UPDATE fact_cards SET detail_ru = '«Сабот уль-оджизин» («Твердыня немощных») — сочинение, написанное стихами на узбекском языке: по просьбе друзей и близких он несколько сократил в нём «Маслак уль-муттакин». За своё нравственно-поучительное значение оно преподавалось в школах и медресе в ряду основных учебников. Источник: Ziyouz.com — раздел «Узбекская классическая словесность».' WHERE id = 1979;
UPDATE fact_cards SET detail_ru = '«Маслак уль-муттакин» написан на персидском языке и состоит из двенадцати тысяч бейтов и ста тридцати пяти глав. На персидском поэт создал ещё сочинения «Мурод уль-орифин» и «Махзан уль-мутиин». Источник: Ziyouz.com — раздел «Узбекская классическая словесность».' WHERE id = 1980;
UPDATE fact_cards SET detail_ru = 'Кроме «Сабот уль-оджизин» он написал на тюркском языке маснави «Фавз ун-нажот» («Торжество спасения») и стихотворное сочинение «Спор плодов». Источник: Ziyouz.com — раздел «Узбекская классическая словесность».' WHERE id = 1981;
UPDATE fact_cards SET detail_ru = 'Суфи Аллаяр умер в 1724 году в Денау. В конце XIX века его сочинения не раз издавались литографским способом в Ташкенте, Казани, Баку и Стамбуле и были переведены на многие иностранные языки. Источник: Ziyouz.com — раздел «Узбекская классическая словесность».' WHERE id = 1982;
